import { isCi } from "../env.js";
import { HEADING_CANCELLED, HEADING_COMPLETE, HEADING_FAILED, HEADING_PENDING, INIT_SUBTITLE } from "./copy.js";
import chalk from "chalk";
//#region src/init/chrome.ts
const NEON_GREEN = "#4BB578";
const INIT_BANNER_LINES = [
	" ██╗  ██╗██████╗ ██████╗ ██╗  ██╗",
	" ███╗ ██║██╔═══╝██╔═══██╗███╗ ██║",
	" ████╗██║██████╗██║   ██║████╗██║",
	" ██╔████║██╔═══╝██║   ██║██╔████║",
	" ██║╚███║██████╗╚██████╔╝██║╚███║",
	" ╚═╝ ╚══╝╚═════╝ ╚═════╝ ╚═╝ ╚══╝"
];
const formatInitBanner = () => INIT_BANNER_LINES.join("\n");
const shouldPrintInitBanner = (yes) => !yes && !isCi() && Boolean(process.stdout.isTTY);
const printInitBanner = () => {
	process.stdout.write(`\n${chalk.hex(NEON_GREEN)(formatInitBanner())}\n\n${chalk.dim(INIT_SUBTITLE)}\n\n`);
};
const printInitProgress = (message) => {
	process.stdout.write(`${message}\n`);
};
const formatInitDone = (input) => {
	const labelWidth = Math.max(0, ...input.rows.map((row) => row.label.length));
	const intro = input.body !== void 0 && input.body.length > 0 ? `\n\n${input.body}` : "";
	const body = input.rows.length === 0 ? "" : `\n\n${input.rows.map((row) => `  ${row.label.padEnd(labelWidth)}  ${row.value}`).join("\n")}`;
	const next = input.next.length === 0 ? "" : `\n\nNext:\n${input.next.map((line) => `  ${line}`).join("\n")}`;
	const rule = "-".repeat(input.heading.length);
	return `${input.heading}\n${rule}${intro}${body}${next}\n`;
};
const headingColor = (heading) => {
	if (heading === "Neon setup complete.") return chalk.hex(NEON_GREEN).bold;
	if (heading === "Neon setup needs a next step.") return chalk.yellow.bold;
	if (heading === "Neon setup failed.") return chalk.red.bold;
	if (heading === "Neon setup cancelled.") return chalk.dim;
	return chalk.hex(NEON_GREEN).bold;
};
const printInitDone = (text) => {
	const lines = (text.endsWith("\n") ? text.slice(0, -1) : text).split("\n");
	const heading = lines[0] ?? "";
	const paintHeading = headingColor(heading);
	const painted = lines.map((line, index) => {
		if (index === 0) return paintHeading(line);
		if (/^-{3,}$/.test(line)) return heading === "Neon setup failed." ? chalk.red(line) : heading === "Neon setup needs a next step." ? chalk.yellow(line) : heading === "Neon setup cancelled." ? chalk.dim(line) : chalk.hex(NEON_GREEN)(line);
		if (line === "Next:") return chalk.bold(line);
		return line;
	});
	process.stdout.write(`\n${painted.join("\n")}\n\n`);
};
const agentSetupLabel = (setup) => {
	if (setup === "plugin") return "plugin";
	if (setup === "skills-mcp") return "skills and MCP";
	if (setup === "skills") return "skills";
	if (setup === "mcp") return "MCP";
	return "skipped";
};
const agentSetupDoneLabel = (input) => {
	if (!input.ran && input.setup !== "skip") return "not run";
	return agentSetupLabel(input.setup);
};
const formatAgentIds = (agents) => agents.join(", ");
const SETUP_LABELS = {
	skip: "skipped",
	plugin: "Neon plugin",
	skills: "skills",
	"skills-mcp": "skills and MCP",
	mixed: "plugin and skills/MCP"
};
/** Names the agents behind each mechanism, since init picks skills and MCP agents separately. */
const agentsRowValue = (input) => {
	const { tooling } = input;
	const parts = [];
	const add = (label, ids) => {
		const ran = ids.filter((id) => input.installed.includes(id));
		if (ran.length > 0) parts.push(`${label}: ${formatAgentIds(ran)}`);
	};
	if (tooling.setup === "plugin" || tooling.setup === "skills") add(SETUP_LABELS[tooling.setup], tooling.agents);
	else if (tooling.setup === "skills-mcp" || tooling.setup === "mixed") {
		if (tooling.setup === "mixed") add("Neon plugin", tooling.pluginAgents);
		if (tooling.skillsAgents.length === tooling.mcpAgents.length && tooling.skillsAgents.every((id) => tooling.mcpAgents.includes(id))) add("skills and MCP", tooling.skillsAgents);
		else {
			add("skills", tooling.skillsAgents);
			add("MCP", tooling.mcpAgents);
		}
	}
	return parts.length > 0 ? parts.join("; ") : SETUP_LABELS[tooling.setup];
};
const projectRowValue = (link) => {
	switch (link) {
		case "already_linked": return "already linked";
		case "linked": return "linked";
		case "claimable": return "claimable";
		case "skipped": return "skipped";
		case null: return "not linked";
		default: return link;
	}
};
const configSummaryLabel = (summary) => {
	switch (summary) {
		case "created": return "neon.ts created";
		case "skipped": return "skipped";
		case "existing": return "existing Neon config";
		case "template": return "provided by template";
		default: return summary;
	}
};
const configRowValue = (config, filename) => {
	if (config === "created") return "neon.ts created";
	if (config === "existing") return `existing ${filename ?? "Neon config"} preserved`;
	if (config === "skipped" || config === null) return "skipped";
	return config;
};
const headingForKind = (kind) => {
	switch (kind) {
		case "success": return HEADING_COMPLETE;
		case "pending": return HEADING_PENDING;
		case "error": return HEADING_FAILED;
		case "aborted": return HEADING_CANCELLED;
		default: return kind;
	}
};
//#endregion
export { INIT_BANNER_LINES, NEON_GREEN, agentSetupDoneLabel, agentSetupLabel, agentsRowValue, configRowValue, configSummaryLabel, formatInitBanner, formatInitDone, headingForKind, printInitBanner, printInitDone, printInitProgress, projectRowValue, shouldPrintInitBanner };
